        ?obs a sosa:Observation ;
             sosa:madeBySensor ?sensor ;
             sosa:hasFeatureOfInterest ?catchment ;
             sosa:observedProperty envthes:30106 ;
             sosa:resultTime ?time ;
             sosa:hasResult ?qv .
        ?qv a qudt:QuantityValue ;
            qudt:numericValue ?precipitationValue ;
            qudt:unit <http://qudt.org/vocab/unit/MilliM> .
        FILTER(STR(?sensorId) = "1001")
        FILTER(STR(?time) >= "2002" && STR(?time) < "2006")
        BIND(SUBSTR(STR(?time), 1, 4) AS ?year)
      }
    }
    GROUP BY ?year
  }
}

